-- ============================================================================
-- 类型映射约定（请勿随意改动）：
--   DDL 中 id 类列（id / tenant_id / created_by / modified_by / dept_id / user_id /
--   role_id / menu_id / parent_id 等）已迁移为 varchar(36)，值为确定性 UUIDv7 风格
--   字面量（逻辑 id N → '00000000-0000-7000-' + hex16(N)，0 → nil UUID，parent_id
--   根 0 → '0'；映射与 db/migration/V2026_10_21__uuid_v7_id.sql 完全一致）。
--   Java 实体（BaseEntity、BaseRelationEntity）对应字段为 String，天然同型；
--   JDBC URL 的 stringtype=unspecified（见 doc/DEFAULT_GROUP/baize-system-dev.yml）
--   保留不冲突。version 为 int4、Java 侧为 Long，属隐式数值转换。
-- ============================================================================

-- 租户数据
-- id 为 nil UUID 的租户是平台级保留租户（平台态）；归属平台租户的数据
-- （如 admin 用户、超级管理员角色、平台种子菜单/部门等）都挂在平台态下；
-- CustomTenantHandler 在租户上下文缺失时兜底为 nil UUID，
-- 保证过滤条件始终可下推为平台租户（平台态隔离，而非跳过过滤）。
INSERT INTO sys_tenant (id, tenant_code, tenant_name, expire_time, contact_person, contact_phone, contact_email, "domain", max_user, sort, status, deleted, "version", created_by, created_time, modified_by, modified_time, remark)
